declare(strict_types=1);

namespace PetstoreClient\Test;

use PetstoreClient\Auth\BearerAuthenticator;

test('raw token is prefixed with bearer', function (): void {
    $auth = new BearerAuthenticator('https://api.example.com', 'xyz');
    $headers = $auth->getAuthHeaders();
    expect($headers['Authorization'])->toBe('Bearer xyz');
});

test('already prefixed token is not doubled', function (): void {
    // Tokens read from env files are commonly stored already-prefixed;
    // emitting "Bearer Bearer xyz" would otherwise silently break auth.
    $auth = new BearerAuthenticator('https://api.example.com', 'Bearer xyz');
    $headers = $auth->getAuthHeaders();
    expect($headers['Authorization'])->toBe('Bearer xyz');
});

test('lowercase bearer prefix is stripped', function (): void {
    $auth = new BearerAuthenticator('https://api.example.com', 'bearer xyz');
    $headers = $auth->getAuthHeaders();
    expect($headers['Authorization'])->toBe('Bearer xyz');
});

test('mixed case bearer prefix is stripped', function (): void {
    $auth = new BearerAuthenticator('https://api.example.com', 'BeArEr xyz');
    $headers = $auth->getAuthHeaders();
    expect($headers['Authorization'])->toBe('Bearer xyz');
});

test('bearer rejects crlf at construction', function (): void {
    expect(fn () => new BearerAuthenticator('https://api.example.com', "tok\r\nInjected: yes"))
        ->toThrow(\InvalidArgumentException::class);
});

test('bearer rejects non ascii at construction', function (): void {
    expect(fn () => new BearerAuthenticator('https://api.example.com', 'ñoño'))
        ->toThrow(\InvalidArgumentException::class);
});

test('bearer rejects empty token at construction', function (): void {
    // An empty / whitespace-only token would emit "Authorization: Bearer "
    // (no credential), so it must be rejected at construction.
    expect(fn () => new BearerAuthenticator('https://api.example.com', ''))
        ->toThrow(\InvalidArgumentException::class, 'Bearer token must not be empty');
    expect(fn () => new BearerAuthenticator('https://api.example.com', '   '))
        ->toThrow(\InvalidArgumentException::class);
});

test('token is masked in var_dump and print_r output', function (): void {
    /* php-authenticator-secret-leaks: __debugInfo() makes PHP's debug dumps
     * (var_dump / print_r / debug_zval_dump) and var_export-style traces use
     * the masked array, so the token never leaks through a stray dump or an
     * exception/stack-trace log. */
    $auth = new BearerAuthenticator('https://api.example.com', 'xyz');

    ob_start();
    var_dump($auth);
    $varDump = (string) ob_get_clean();

    $printR = print_r($auth, true);

    expect($varDump)->not->toContain('token=xyz');
    expect($varDump)->toContain('***');
    expect($printR)->not->toContain('token=xyz');
    expect($printR)->toContain('***');
});

test('secret constructor parameters are marked sensitive', function (): void {
    $sensitive = [];
    foreach ((new \ReflectionMethod(BearerAuthenticator::class, '__construct'))->getParameters() as $param) {
        if ($param->getAttributes(\SensitiveParameter::class) !== []) {
            $sensitive[] = $param->getName();
        }
    }
    expect($sensitive)->toBe(['token']);
});

test('rejected token is not recorded in the exception stack trace', function (): void {
    // Exception backtraces record call arguments when zend.exception_ignore_args
    // is Off (the built-in default); a sensitive parameter is replaced by a
    // placeholder so the secret never reaches getTraceAsString().
    $previous = ini_set('zend.exception_ignore_args', '0');
    try {
        new BearerAuthenticator('https://api.example.com', "tk\x01SECRETVALUE");
        $trace = '';
    } catch (\InvalidArgumentException $e) {
        $trace = $e->getTraceAsString();
    } finally {
        ini_set('zend.exception_ignore_args', $previous === false ? '1' : $previous);
    }
    expect($trace)->not->toBe('');
    expect($trace)->not->toContain('SECRET');
});

test('debug output keeps the host and masks only the token', function (): void {
    $auth = new BearerAuthenticator('https://api.example.com', 'xyz');

    $printR = print_r($auth, true);

    expect($printR)->toContain('[host] => https://api.example.com');
    expect($printR)->toContain('[token] => ***');
});

test('every generated bearer wrapper sends the bearer header and masks the token', function (): void {
    $wrappers = 0;
    foreach (glob(dirname(__DIR__) . '/lib/Auth/*Authenticator.php') ?: [] as $file) {
        $class = 'PetstoreClient\\Auth\\' . basename($file, '.php');
        if (!is_subclass_of($class, BearerAuthenticator::class)) {
            continue;
        }
        $wrappers++;
        $reflection = new \ReflectionClass($class);

        $auth = $reflection->newInstance('https://api.example.com', 'wrapper-token');
        expect($auth->getAuthHeaders())->toBe(['Authorization' => 'Bearer wrapper-token']);
        expect(print_r($auth, true))->not->toContain('wrapper-token');
        expect(fn () => $reflection->newInstance('https://api.example.com', ''))
            ->toThrow(\InvalidArgumentException::class);
    }
    expect($wrappers)->toBeGreaterThan(0);
});
